---刷新节点
---@param star        integer 星级
---@param attrId      integer 属性id
---@param attrNum     integer 属性数值
---@param attrQuality integer 属性品质
---@param equipmentId integer 装备id
---@param selectedIdx integer | nil 选中的属性序号
function CardProgressionEquipmentRecastAttrNode:RefreshNode(star, attrId, attrNum, attrQuality, equipmentId, selectedIdx)
    KTool.SetActive(self.AttrNode, true)
    local attrVo = cardConfMgr:GetBasicAttrAdditionById(attrId)
    CfUtils.FillText(self.AttrNameText, attrVo.attrAdditionName)
    EquipUtils.SwitchSubAttrColorByQuality(self.ImgBg2, attrQuality)
    local percent = EquipUtils.GetSubAttrPercent(equipmentId, attrId, attrNum)
    self.Slider.value = percent
    CfUtils.FillText(self.AttrNumText, '+' .. attribute_format(attrVo.isConversion, attrNum))
    CfUtils.SetUISwitchImage(self.ImgPointRare, attrQuality)
    
    local isLock = checkInt(star) < self:GetIndex()

    KTool.SetActive(self.LockNode, isLock)
    self.ImgBaseBgShadow.enabled = not isLock
    
    if not isLock and checkInt(selectedIdx) > 0 then
        CfUtils.SetUISwitchImage(self.ImgBaseBg, selectedIdx == self:GetIndex() and 1 or 2)
    else
        CfUtils.SetUISwitchImage(self.ImgBaseBg, 1)
    end

    local goodsId = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentCuringGoodsId))
    local goodsNum = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentCuringGoodsNum))
    CfUtils.FillFontStyleWithGoodIconButtonNode(self.FontStyleWithGoodIconButton, goodsId,'x' .. goodsNum)
end

---刷新选中状态
---@param isSelected boolean 是否选中
function CardProgressionEquipmentRecastAttrNode:RefreshSelectedState(isSelected)
    CfUtils.PlayAnimation(self.AttrNode, isSelected and AttrNodeAniName.LOCKING or AttrNodeAniName.UNLOCK)
end

---播放洗练动画
function CardProgressionEquipmentRecastAttrNode:PlayRecastAnimation()
    CfUtils.PlayAnimation(self.controller.gameObject, "CultivateOverseaEquipmentClearDialogReset")
end
--endregion public

--region private
function CardProgressionEquipmentRecastAttrNode:GetIndex()
    return checkInt(self._index)
end
